import {bowPath,samplePath,weaponAxes} from '../weapon-paths.js?v=14';
import {enchantVisual} from '../combat.js?v=14';
// Original art sheets. UV cropping is performed at runtime; original alpha is preserved.
export const visualAssets={hero:null,terrain:null,wolf:null,weapon:null,ready:false,loaded:0,errors:[]};
const entries=[['petForms','assets/pet-forms-v7.webp'],['pressureBurst','assets/pressure-burst-v7.webp'],['weaponEnergy','assets/weapon-energy-v5.webp'],['ground','assets/ground-v5.webp'],['scenery','assets/scenery-v5.webp'],['mobs','assets/mobs-v5.webp'],['presence','assets/presence-v5.webp'],['npcs','assets/npcs-v4.webp'],['companions','assets/companions-v4.webp'],['sigils','assets/sigils-v4.webp'],['ruptorMotion','assets/ruptor-motion-v3.webp'],['attackMotion','assets/attacks-v3.webp'],['effects','assets/effects-v3.webp'],['classes','assets/classes-atlas-v2.webp'],['relics','assets/relics-atlas-v2.webp'],['arsenal','assets/arsenal-atlas-v2.webp'],['hero','assets/warrior-atlas-v1.webp'],['terrain','assets/garden-atlas-v1.webp'],['wolf','assets/wolf-atlas-v1.webp'],['weapon','assets/weapon-atlas-v1.webp']];
export const visualAssetsReady=Promise.all(entries.map(([key,url])=>new Promise(resolve=>{const image=new Image();image.onload=()=>{visualAssets[key]=image;visualAssets.loaded++;resolve(true);};image.onerror=()=>{visualAssets.errors.push(url);resolve(false);};image.src=url;}))).then(values=>{visualAssets.ready=values.every(Boolean);return visualAssets.ready;});
export function drawCell(g,image,columns,rows,index,x,y,w,h){if(!image)return false;const cw=(image.naturalWidth||image.width)/columns,ch=(image.naturalHeight||image.height)/rows;g.drawImage(image,(index%columns)*cw,Math.floor(index/columns)*ch,cw,ch,x,y,w,h);return true;}
export function drawScenery(g,kind,seed=0){const a=visualAssets.terrain;if(!a)return false;if(kind==='tree'){g.save();g.scale(seed%2?-1:1,1);drawCell(g,a,2,2,2,-68,-122,136,136);g.restore();return true;}if(['ruin','pillar','lighthouse','house'].includes(kind)){drawCell(g,a,2,2,3,-64,-114,128,128);return true;}return false;}
export function paintGardenTile(g,type,x,y){const a=visualAssets.ground||visualAssets.terrain;if(!a||!['grass','path','stone','sand'].includes(type))return false;g.save();g.transform(27/512,13.5/512,-27/512,13.5/512,x,y);drawCell(g,a,2,2,visualAssets.ground?({grass:0,path:1,stone:2,sand:3}[type]):type==='grass'?0:1,0,0,512,512);g.restore();return true;}
export function drawWarriorSprite(g,moving,t,attack,a={}){if(!visualAssets.hero)return false;const frame=attack?8+Math.min(3,Math.floor((a.attackProgress||0)*4)):moving?4+Math.floor(t*9)%4:Math.floor(t*2)%4;g.save();const bob=moving?Math.sin(t*18)*.7:Math.sin(t*2)*.5;g.translate(0,bob);if(a.facingLeft)g.scale(-1,1);drawCell(g,visualAssets.hero,4,3,frame,-48,-122,96,128);g.restore();return true;}
export function drawWolfSprite(g,e,t){if(!visualAssets.wolf)return false;const frame=e.flash>0?8:e.winding>0?6+Math.floor(t*8)%2:e.moving?3+Math.floor(t*9)%3:Math.floor(t*2)%3;g.save();if(e.facing?.x+e.facing?.y<0)g.scale(-1,1);drawCell(g,visualAssets.wolf,3,3,frame,-45,-65,90,90);g.restore();return true;}

export const CLASS_CELLS={VIG:0,ESP:1,ARC:2,BAS:3,RUP:4,DUE:5,LAS:6};
export function drawClassSprite(g,id,moving,t,attack,a={}){
 if(!visualAssets.classes||CLASS_CELLS[id]===undefined||a.hasWeapon===false||a.hasArmor===false||a.hasSecondary===false&&id!=='RUP'||['hasHead','hasHands','hasLegs','hasBoots'].some(k=>a[k]===false))return false;
 g.save();if(a.facingLeft)g.scale(-1,1);const phase=a.attackProgress||0;
 g.translate(attack?Math.sin(phase*Math.PI)*4:0,moving?-Math.abs(Math.sin(t*9))*2:Math.sin(t*1.8)*.5);
 g.rotate(attack?Math.sin(phase*Math.PI)*.055:0);
 const ev=enchantVisual(a.enchant||0);g.shadowColor=ev.color;g.shadowBlur=ev.stage>=4?4:ev.stage>=2?2:0;if(id==='RUP'&&visualAssets.ruptorMotion){const frame=attack?8+Math.min(3,Math.floor(phase*4)):moving?4+Math.floor(t*8)%4:Math.floor(t*1.5)%4;drawCell(g,visualAssets.ruptorMotion,4,3,frame,-64,-122,128,128);}else if(attack&&visualAssets.attackMotion){const row={VIG:0,ESP:1,ARC:2,BAS:3,DUE:4,LAS:5}[id];drawCell(g,visualAssets.attackMotion,4,6,row*4+Math.min(3,Math.floor(phase*4)),-64,-122,128,128);}else drawCell(g,visualAssets.classes,4,2,CLASS_CELLS[id],-48,-122,96,128);g.shadowBlur=0;
 // Energy is attached to the same transform as the weapon and hand.
 const enchant=a.enchant||0;if(Math.max(enchant,a.secondaryEnchant||0)>=5){g.globalCompositeOperation='lighter';
 const paths={VIG:[[30,-91,41,-34],[-12,-89,-20,-59]],ESP:[[-37,-53,-15,-69],[24,-41,39,-57]],ARC:[[-29,-104,-28,-20],[25,-83,28,-76]],BAS:[[0,-50,37,-26],[-29,-67,-22,-32]],RUP:[[7,-62,63,-29]],DUE:[[-35,-25,-10,-63],[19,-48,36,-22]],LAS:[[-19,-57,40,-33],[25,-81,28,-75]]};
 for(const [pathIndex,[x,y,ex,ey]] of weaponAxes(id,attack,phase,paths[id]).entries()){const ev=enchantVisual(pathIndex>0?(a.secondaryEnchant??enchant):enchant),c=ev.color;if(ev.stage===0)continue;if(id==='VIG'&&pathIndex===0){drawBowEnergy(g,enchant,t,attack,phase);continue;}drawLivingWeaponEnergy(g,x,y,ex,ey,pathIndex>0?(a.secondaryEnchant??enchant):enchant,t+pathIndex*.7,attack);for(let n=0;n<ev.motes;n++){const q=(t*(.3+ev.intensity*.4)+n/ev.motes)%1;g.globalAlpha=(.3+Math.sin(q*Math.PI)*.5)*Math.min(1,(pathIndex>0?(a.secondaryEnchant||0):enchant)/10);g.fillStyle=n%2?c:'#ffffff';g.beginPath();g.arc(x+(ex-x)*q,y+(ey-y)*q,1+n%2*.35,0,Math.PI*2);g.fill();}g.strokeStyle=c;g.shadowColor=c;g.shadowBlur=4+ev.stage;g.lineWidth=id==='VIG'?2:1;g.globalAlpha=.28+ev.intensity*(.3+.15*Math.sin(t*3));g.beginPath();g.moveTo(x,y);g.lineTo(ex,ey);g.stroke();if(ev.stage>=4){g.lineWidth=ev.stage===5?5:3;g.globalAlpha=ev.stage===5?.18:.10;g.stroke();}if(ev.stage===5){for(let n=0;n<3;n++){const q=(t*.8+n/3)%1;g.globalAlpha=Math.sin(q*Math.PI)*.8;g.fillStyle=n%2?'#ffb5ff':'#cfffff';g.beginPath();g.arc(x+(ex-x)*q+Math.sin(t*9+n)*3,y+(ey-y)*q+Math.cos(t*9+n)*3,1.7,0,Math.PI*2);g.fill();}}}}
 g.restore();return true;
}

// Energy rises from the weapon axis rather than orbiting the whole character.
export function drawLivingWeaponEnergy(g,x,y,ex,ey,rank,t,attack=false){
 const ev=enchantVisual(rank);if(!ev.stage)return;const length=Math.hypot(ex-x,ey-y),angle=Math.atan2(ey-y,ex-x)+Math.PI/2;
 g.save();g.translate((x+ex)/2,(y+ey)/2);g.rotate(angle);g.globalCompositeOperation='lighter';
 const pulse=.86+.14*Math.sin(t*2.4),width=5+ev.stage*2.2,height=length+ev.stage*5;
 if(visualAssets.weaponEnergy){g.globalAlpha=(.24+ev.stage*.10)*pulse;drawCell(g,visualAssets.weaponEnergy,3,2,ev.stage,-width,-height*.56,width*2,height);}
 const glow=g.createLinearGradient(-width,0,width,0);glow.addColorStop(0,ev.color+'00');glow.addColorStop(.46,ev.color+(ev.stage===5?'88':'33'));glow.addColorStop(.5,'#faffffbb');glow.addColorStop(.54,ev.color+'55');glow.addColorStop(1,ev.color+'00');g.globalAlpha=pulse;g.fillStyle=glow;g.fillRect(-width,-length/2,width*2,length);
 const count=ev.stage===5?18:ev.stage*2;for(let n=0;n<count;n++){const q=(t*(.45+ev.stage*.09)+n*.618)%1,side=n%2?1:-1,spread=Math.sin(q*Math.PI)*(ev.stage===5?18:ev.stage*1.7);g.globalAlpha=(1-q)*(.45+ev.stage*.08);g.strokeStyle=n%3?'#e8ffff':ev.color;g.lineWidth=ev.stage===5?1.1:.7;const xx=side*spread,yy=length*.5-q*(length+25);g.beginPath();g.moveTo(xx*.7,yy+4);g.quadraticCurveTo(xx+Math.sin(t*5+n)*2,yy,xx,yy-3-ev.stage);g.stroke();}
 if(ev.stage===5){g.globalAlpha=.4+.2*Math.sin(t*3);g.strokeStyle='#fff';g.lineWidth=1.3;for(let n=0;n<2;n++){g.beginPath();for(let k=0;k<8;k++){const xx=Math.sin(k*2.1+Math.floor(t*9)+n)*4,yy=-length*.5+k*length/7;k?g.lineTo(xx,yy):g.moveTo(xx,yy);}g.stroke();}}
 g.restore();
}

export function drawBowEnergy(g,rank,t,attack=false,phase=0,pointsOverride=null){const ev=enchantVisual(rank);if(!ev.stage)return;const points=pointsOverride||bowPath(attack,phase);g.save();g.globalCompositeOperation='lighter';g.lineJoin='round';g.lineCap='round';const path=()=>{g.beginPath();points.forEach(([x,y],n)=>n?g.lineTo(x,y):g.moveTo(x,y));};g.strokeStyle=ev.color;g.shadowColor=ev.color;g.shadowBlur=5+ev.stage*1.5;g.globalAlpha=.30+ev.stage*.08+Math.sin(t*3)*.06;g.lineWidth=1+ev.stage*.4;path();g.stroke();g.shadowBlur=0;g.globalAlpha=.07+ev.stage*.025;g.lineWidth=3+ev.stage*1.7;path();g.stroke();const count=ev.stage===5?24:ev.stage*3;for(let n=0;n<count;n++){const q=(t*(.35+ev.stage*.07)+n*.618)%1,p=samplePath(points,q),side=n%2?1:-1,spread=Math.sin(q*Math.PI)*(ev.stage===5?8:ev.stage*.8),x=p.x+Math.cos(p.angle+Math.PI/2)*spread*side,y=p.y+Math.sin(p.angle+Math.PI/2)*spread*side;g.globalAlpha=Math.sin(q*Math.PI)*(.4+ev.stage*.07);g.strokeStyle=n%3?'#f0ffff':ev.color;g.lineWidth=ev.stage===5?1.3:.8;g.beginPath();g.moveTo(x-Math.cos(p.angle)*3,y-Math.sin(p.angle)*3);g.lineTo(x,y);g.stroke();}if(ev.stage===5){g.globalAlpha=.5;g.strokeStyle='#fff';g.lineWidth=1;g.beginPath();for(let n=0;n<=16;n++){const p=samplePath(points,n/16),offset=Math.sin(n*2.2+Math.floor(t*10))*2;n?g.lineTo(p.x+offset,p.y-offset):g.moveTo(p.x,p.y);}g.stroke();}g.restore();}
